'use strict';
const fs=require('fs'),vm=require('vm'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto');
const base=path.resolve(__dirname,'../ASSETS'),record=require(path.join(base,'record-tools.js'));
let passed=0;function test(name,fn){fn();passed++;console.log('PASS '+name);}
const row=(name,score='')=>({name,ww:[score],pt:[''],qa:['']});
const period=score=>({locked:false,wwHps:['20'],ptHps:['20'],qaHps:['20'],wwDates:['2026-10-24'],ptDates:[''],qaDates:[''],roster:[row('Synthetic, Learner',score)]});
test('Grading-engine bytes match the existing repository version',()=>{const b=fs.readFileSync(path.join(base,'grading-engine.js'));assert.equal(crypto.createHash('sha1').update(Buffer.concat([Buffer.from('blob '+b.length+'\0'),b])).digest('hex'),'79f469842b84a798be88717561696760344219af');});
test('Cancellation at full HPS restores raw score and archives every addition',()=>{const p=period('18.00');record.addPoints(p,'ww',0,0,1,'First');record.addPoints(p,'ww',0,0,1,'Second');record.removePoints(p,'ww',0,0,'Cancelled');assert.equal(p.roster[0].ww[0],'18.00');assert.equal(p.roster[0].scoreAdjustments.ww[0].history[0].entries.length,2);});
test('Cancellation preserves a zero raw score exactly',()=>{const p=period('0.00');record.addPoints(p,'ww',0,0,2,'Reason');record.removePoints(p,'ww',0,0,'Cancelled');assert.equal(p.roster[0].ww[0],'0.00');});
test('Cancellation keeps all other learners and components unchanged',()=>{const p=period('8.50');p.roster.push(row('Other, Learner','9'));const before=JSON.stringify(p.roster[1]);record.addPoints(p,'ww',0,0,2,'Reason');record.removePoints(p,'ww',0,0,'Cancelled');assert.equal(p.roster[0].ww[0],'8.50');assert.equal(JSON.stringify(p.roster[1]),before);assert.deepEqual(p.roster[0].pt,['']);});
test('Recognized empty strand headings are protected',()=>{for(const name of ['STEM-EAD','STEM','ABM A','HUMSS-12','TVL ICT','GAS'])assert.equal(record.getRowCategory(row(name)),'section');});
test('Scored strand-like names remain learner rows',()=>{for(const score of ['0','8','A','L','M','E'])assert.equal(record.getRowCategory(row('STEM-EAD',score)),null);});
test('Personal names are not silently converted to section headings',()=>{for(const name of ['STEM, Alex','Boysen, Alex','Girls, Bea','STEM Academy Student','Stem Ead'])assert.equal(record.getRowCategory(row(name)),null);});
test('Boys and girls headings retain their separate category identity',()=>{assert.equal(record.getRowCategory(row('Grade 8 BOYS')),'boys');assert.equal(record.getRowCategory(row('GIRLS · STEM-EAD')),'girls');});
const noop=()=>{};const element={dataset:{theme:'light'},addEventListener:noop,querySelector:()=>null,querySelectorAll:()=>[],classList:{add:noop,remove:noop,toggle:noop},style:{},getBoundingClientRect:()=>({width:1280,height:720})};const storage={getItem:()=>null,setItem:noop,removeItem:noop};
const ctx={console,setTimeout:()=>0,clearTimeout:noop,setInterval:()=>0,clearInterval:noop,Date,Math,localStorage:storage,sessionStorage:storage,matchMedia:()=>({matches:false,addEventListener:noop}),document:{querySelector:s=>s==='#app'?element:null,querySelectorAll:()=>[],addEventListener:noop,documentElement:element,body:element},window:{addEventListener:noop},requestAnimationFrame:noop,cancelAnimationFrame:noop,ResizeObserver:class{observe(){}}};
ctx.window.CSTRGrading=require(path.join(base,'grading-engine.js'));ctx.window.CSTRRecordTools=record;
vm.runInNewContext(fs.readFileSync(path.join(base,'app.js'),'utf8').replace('  initApp();','  window.testHooks={normalizeState,createInitialState,renderSectionRecord,deleteRosterRow,learnerResult,setState(v){state=normalizeState(v);activeSectionId=state.registry[0].id;},getState(){return state;}};'),ctx);
const h=ctx.window.testHooks,s=h.createInitialState();s.registry=[{id:'test',subject:'Synthetic',section:'A',group:'JHS',level:'8',weights:[30,40,30],rosterSize:3}];h.setState(s);
test('Saved scores and adjustment histories survive normalization exactly',()=>{const s=h.getState(),p=s.sections.test.periods[0];p.roster[0].name='Synthetic, Learner';p.roster[0].ww[0]='8.50';p.wwHps[0]='20';record.addPoints(p,'ww',0,0,2,'Original reason');record.removePoints(p,'ww',0,0,'Cancelled');const before=p.roster.map(l=>({...l,hpsOriginals:l.hpsOriginals||{},scoreAdjustments:l.scoreAdjustments||{}}));const normalized=h.normalizeState(JSON.parse(JSON.stringify(s)));assert.deepEqual(JSON.parse(JSON.stringify(normalized.sections.test.periods[0].roster)),JSON.parse(JSON.stringify(before)));});
test('Rendering does not change saved teacher, roster, dates, or scores',()=>{const before=JSON.stringify(h.getState());h.renderSectionRecord();assert.equal(JSON.stringify(h.getState()),before);});
test('Category deletion handler rejects boys, girls and strand headings',()=>{for(const name of ['BOYS','GIRLS','STEM-EAD']){const p=h.getState().sections.test.periods[0];p.roster[1].name=name;const before=JSON.stringify(h.getState());h.deleteRosterRow(1);assert.equal(JSON.stringify(h.getState()),before);}});
test('Category rows have no delete action, while learner rows still do',()=>{const p=h.getState().sections.test.periods[0];p.roster[1].name='STEM-EAD';p.roster[2].name='Other, Learner';const html=h.renderSectionRecord();const category=html.match(/<tr class="row-category row-category-section"[\s\S]*?<\/tr>/)[0];assert(!category.includes('delete-roster-row'));assert(html.includes('data-action="delete-roster-row" data-row="2"'));});
console.log(`${passed} October 24 regression checks passed.`);
